// rig_test stage-only: main-thread read observations. No campaign/native financial writes.
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace PerformanceReview {
public class C1Runner:MonoBehaviour {
 public static C1Runner Instance; public string Root;
 static readonly BindingFlags BF=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static readonly Assembly PC=typeof(PersistentCity.Runtime.PopulationRuntime).Assembly;
 Type readerType,sourceType; MethodInfo facade; object reader; PersistentCity.Runtime.PopulationRuntime cachedRuntime; int[] selected=new int[0];
 bool running,cold; bool mixed; int scope,repeats,target; long initialHeap; Func<long> allocated; bool allocationValid;
 readonly List<Row> rows=new List<Row>(65536);
 public struct Row {public int frame;public string phase;public double ms;public long bytes;}
 void Awake(){Instance=this;DontDestroyOnLoad(gameObject);readerType=PC.GetType("PersistentCity.Runtime.NativeCampaignReader");sourceType=PC.GetType("PersistentCity.Runtime.CampaignBusinessSource");facade=typeof(PersistentCity.Runtime.PopulationRuntime).GetMethod("ReadCampaignSnapshot");var m=typeof(GC).GetMethod("GetAllocatedBytesForCurrentThread",Type.EmptyTypes);if(m!=null){allocated=(Func<long>)Delegate.CreateDelegate(typeof(Func<long>),m);long a=allocated();var b=new byte[4096];allocationValid=allocated()>a;GC.KeepAlive(b);}}
 static string Hash(string s){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(System.Text.Encoding.UTF8.GetBytes(s))).Replace("-","").ToLowerInvariant();}
 static string Json(object o)=>JsonConvert.SerializeObject(o,Formatting.None);
 static object Fields(object obj,int depth,HashSet<object> seen){if(obj==null)return null;var t=obj.GetType();if(t.IsPrimitive||t.IsEnum||obj is string||obj is decimal)return obj;if(obj is UnityEngine.Object u)return new{unityType=t.FullName,id=u==null?0:u.GetInstanceID()};if(depth<=0)return new{truncatedType=t.FullName};if(!t.IsValueType&&!seen.Add(obj))return new{cycle=t.FullName};try{if(obj is IDictionary dict){var d=new SortedDictionary<string,object>();foreach(DictionaryEntry e in dict)d[Convert.ToString(e.Key)]=Fields(e.Value,depth-1,seen);return d;}if(obj is IEnumerable seq){var list=new List<object>();foreach(var v in seq)list.Add(Fields(v,depth-1,seen));return list;}var fields=new SortedDictionary<string,object>();foreach(var f in t.GetFields(BF)){if(f.IsStatic||typeof(Delegate).IsAssignableFrom(f.FieldType))continue;fields[f.Name]=Fields(f.GetValue(obj),depth-1,seen);}return fields;}finally{if(!t.IsValueType)seen.Remove(obj);}}
 static object Raw(object o)=>Fields(o,20,new HashSet<object>());
 static double Minute=>SaveGameManager.Current.Day*1440.0+SaveGameManager.Current.Hour*60+SaveGameManager.Current.Minute;
 static PersistentCity.Runtime.PopulationRuntime Runtime()=>UnityEngine.Object.FindObjectOfType<PersistentCity.Runtime.PopulationRuntime>();
 void Select(){var regs=SaveGameManager.Current.BuildingRegistrations;var identity=PC.GetType("PersistentCity.Runtime.FoodBusinessCatalogue").GetMethod("BusinessIdentity",BindingFlags.Static|BindingFlags.NonPublic);selected=Enumerable.Range(0,regs.Count).Where(i=>regs[i]!=null&&!string.IsNullOrWhiteSpace(regs[i].StreetName)).OrderByDescending(i=>regs[i].marketingCampaigns!=null&&regs[i].marketingCampaigns.Count>0).ThenByDescending(i=>regs[i].HasEstablishedBusiness).GroupBy(i=>(string)identity.Invoke(null,new object[]{regs[i]})).Select(g=>g.First()).Take(1024).ToArray();}
 object Sources(int count){var regs=SaveGameManager.Current.BuildingRegistrations;var a=Array.CreateInstance(sourceType,count);for(int i=0;i<count;i++)a.SetValue(Activator.CreateInstance(sourceType,new object[]{"rig:registration:"+selected[i],regs[selected[i]]}),i);return a;}
 object Read(object r,object sources,int budget=64,double? at=null,long revision=0){double minute=at??Minute;var refresh=readerType.GetMethod("Begin").Invoke(r,new object[]{sources,minute,revision});while((int)refresh.GetType().GetProperty("Cursor").GetValue(refresh)<((Array)sources).Length)refresh.GetType().GetMethod("Step").Invoke(refresh,new object[]{budget,minute,revision});return refresh.GetType().GetProperty("Snapshot").GetValue(refresh);}
 object CustomerStatics(){return typeof(BuildingRegistration).Assembly.GetTypes().Where(t=>t.Name=="CustomerEntriesHelper").ToDictionary(t=>t.FullName,t=>t.GetFields(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Where(f=>!typeof(Delegate).IsAssignableFrom(f.FieldType)).OrderBy(f=>f.Name).ToDictionary(f=>f.Name,f=>Raw(f.GetValue(null))));}
 object Native(){Select();var save=SaveGameManager.Current;var regs=save.BuildingRegistrations;var names=new[]{"customer","cash","transaction","financ","marketing","promotion","money","bank","income","expense","account"};var fields=save.GetType().GetFields(BF).Where(f=>names.Any(n=>f.Name.ToLowerInvariant().Contains(n))).OrderBy(f=>f.Name).ToDictionary(f=>f.Name,f=>Raw(f.GetValue(save)));return new{minute=Minute,revision=0,selected,registrationCount=regs.Count,selectedCount=selected.Length,campaignEntries=selected.Sum(i=>regs[i].marketingCampaigns?.Count??0),registrations=selected.Select(i=>new{index=i,fields=typeof(BuildingRegistration).GetFields(BF).Where(f=>names.Any(n=>f.Name.ToLowerInvariant().Contains(n))||new[]{"streetName","streetNumber","StreetName","StreetNumber","businessTypeName","creationDay"}.Contains(f.Name)).OrderBy(f=>f.Name).ToDictionary(f=>f.Name,f=>Raw(f.GetValue(regs[i])))}).ToArray(),saveFields=fields,customerStatics=CustomerStatics()};}
 object Metadata(){return new{available=readerType!=null,facade=facade!=null,frame=Time.frameCount,loaded=PC.Location,moduleMvid=PC.ManifestModule.ModuleVersionId.ToString(),loadedFileSha256=HashFile(PC.Location),nativeAssemblies=new[]{typeof(BuildingRegistration).Assembly,typeof(Address).Assembly}.Distinct().Select(a=>new{name=a.GetName().Name,sha256=HashFile(a.Location),mvid=a.ManifestModule.ModuleVersionId.ToString()}).ToArray(),registrationFields=typeof(BuildingRegistration).GetFields(BF).Select(f=>new{name=f.Name,type=f.FieldType.FullName}).ToArray(),saveFields=SaveGameManager.Current.GetType().GetFields(BF).Select(f=>new{name=f.Name,type=f.FieldType.FullName}).ToArray(),campaignFields=typeof(Entities.MarketingCampaign).GetFields(BF).Select(f=>new{name=f.Name,type=f.FieldType.FullName}).ToArray(),enumUnderlying=Enum.GetUnderlyingType(typeof(Entities.MarketingTypeName)).FullName,enumValues=Enum.GetValues(typeof(Entities.MarketingTypeName)).Cast<object>().Select(v=>new{name=v.ToString(),code=Convert.ToInt32(v)}).ToArray(),reviewed=readerType==null?null:PC.GetType("PersistentCity.Core.CampaignTypeGroups").GetProperty("Reviewed").GetValue(null),allocationCounterValid=allocationValid};}
 static string HashFile(string p){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 object Dumps(){Select();return new{minute=Minute,revision=0,scopes=new[]{1,Math.Min(8,selected.Length),selected.Length}.Distinct().Select(n=>new{count=n,indices=selected.Take(n).ToArray(),dto=facade.Invoke(Runtime(),new object[]{selected.Take(n).ToArray()})}).ToArray()};}
 object Repeated(JObject q){Select();int n=(int?)q["scope"]??Math.Min(8,selected.Length);int count=(int?)q["repeats"]??100;string first=null,last=null;bool same=true;double minute=Minute;for(int i=0;i<count;i++){string s=Json(facade.Invoke(Runtime(),new object[]{selected.Take(n).ToArray()}));if(i==0)first=s;last=s;same&=s==first;}return new{count,scope=n,minuteBefore=minute,minuteAfter=Minute,firstSha256=Hash(first),lastSha256=Hash(last),allIdentical=same};}
 object Diagnostics(){
  var results=new List<object>();var regs=SaveGameManager.Current.BuildingRegistrations;Select();
  Action<string,Action> refuse=(name,act)=>{try{act();results.Add(new{name,refused=false});}catch(Exception e){results.Add(new{name,refused=true,error=(e.InnerException??e).GetType().Name});}};
  refuse("duplicate-index",()=>facade.Invoke(Runtime(),new object[]{new[]{selected[0],selected[0]}}));refuse("missing-index",()=>facade.Invoke(Runtime(),new object[]{new[]{regs.Count}}));
  object sources=Sources(Math.Min(8,selected.Length));var r=Activator.CreateInstance(readerType);var begin=readerType.GetMethod("Begin");var f=begin.Invoke(r,new object[]{sources,Minute,7L});var ft=f.GetType();ft.GetMethod("Step").Invoke(f,new object[]{1,Minute,7L});results.Add(new{name="bounded-unit",cursor=ft.GetProperty("Cursor").GetValue(f),partialUnpublished=ft.GetProperty("Snapshot").GetValue(f)==null});ft.GetMethod("Step").Invoke(f,new object[]{1,Minute,8L});results.Add(new{name="revision-change",refused=ft.GetProperty("Refused").GetValue(f),unpublished=ft.GetProperty("Snapshot").GetValue(f)==null});
  f=begin.Invoke(r,new object[]{sources,Minute,7L});ft.GetMethod("Step").Invoke(f,new object[]{1,Minute+1,7L});results.Add(new{name="minute-change",refused=ft.GetProperty("Refused").GetValue(f),unpublished=ft.GetProperty("Snapshot").GetValue(f)==null});
  var asm=Assembly.LoadFrom(Path.Combine(Root,"C1Doubles.fixture"));foreach(var kind in new[]{"six","disabled","none","unsupported","duplicate","missing","changed","changed-enum"}){var reg=asm.GetType("DoubleFactory").GetMethod("Create").Invoke(null,new object[]{kind});var a=Array.CreateInstance(sourceType,1);a.SetValue(Activator.CreateInstance(sourceType,new object[]{"double:"+kind,reg}),0);results.Add(new{name=kind,detached=true,snapshot=Read(Activator.CreateInstance(readerType),a,1)});}
  return results;
 }
 object Memory(){Select();int n=(int?)memoryScope??8;n=Math.Min(n,selected.Length);var r=Activator.CreateInstance(readerType);var sources=Sources(n);Read(r,sources);long before=GC.GetTotalMemory(true);var held=new object[32];for(int i=0;i<held.Length;i++)held[i]=Read(r,sources);long after=GC.GetTotalMemory(true);GC.KeepAlive(held);return new{scope=n,images=32,before,after,retainedBytesPerImage=Math.Max(0,after-before)/32,allocationCounterValid=allocationValid};}
 int? memoryScope;
 object EntryCost(){Select();var rows=new List<object>();var runtime=Runtime();foreach(int n in new[]{1,8,selected.Length})for(int i=0;i<11;i++){long t=Stopwatch.GetTimestamp();var found=Runtime();double lookupMs=(Stopwatch.GetTimestamp()-t)*1000.0/Stopwatch.Frequency;var indices=selected.Take(n).ToArray();t=Stopwatch.GetTimestamp();var dto=facade.Invoke(runtime,new object[]{indices});double facadeMs=(Stopwatch.GetTimestamp()-t)*1000.0/Stopwatch.Frequency;GC.KeepAlive(dto);rows.Add(new{scope=n,iteration=i,lookupMs,facadeMs,sameRuntime=ReferenceEquals(found,runtime),frame=Time.frameCount});}return rows;}
 public object Command(JObject q){string action=(string)q["action"];if(action=="metadata")return Metadata();if(action=="native")return Native();if(readerType==null)return new{available=false};if(action=="entry-cost")return EntryCost();if(action=="dumps")return Dumps();if(action=="repeat")return Repeated(q);if(action=="diagnostics")return Diagnostics();if(action=="memory"){memoryScope=(int?)q["scope"];return Memory();}if(action=="arm"){running=false;cachedRuntime=Runtime();Select();scope=Math.Min((int?)q["scope"]??8,selected.Length);cold=(bool?)q["cold"]??false;mixed=(bool?)q["mixed"]??false;target=(int?)q["repeats"]??int.MaxValue;repeats=0;rows.Clear();reader=Activator.CreateInstance(readerType);initialHeap=GC.GetTotalMemory(true);return new{scope,cold,target,initialHeap};}if(action=="start"){running=true;return new{frame=Time.frameCount,scope,cold};}if(action=="status")return new{running,repeats};if(action=="stop"){running=false;string file="c1-"+(string)q["id"]+".csv";using(var w=new StreamWriter(Path.Combine(Root,file))){w.WriteLine("frame,phase,ms,bytes");foreach(var x in rows)w.WriteLine(x.frame+","+x.phase+","+x.ms.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+x.bytes);}return new{scope,cold,repeats,file,initialHeap,heap=GC.GetTotalMemory(false),allocationCounterValid=allocationValid};}throw new Exception("Unknown C1 action");}
 void Update(){if(!running)return;try{long bytes=allocationValid?allocated():-1;long start=Stopwatch.GetTimestamp();bool isCold=cold||(mixed&&repeats%2==0);object dto;if(isCold){dto=Read(Activator.CreateInstance(readerType),Sources(scope));}else dto=facade.Invoke(cachedRuntime,new object[]{selected.Take(scope).ToArray()});double ms=(Stopwatch.GetTimestamp()-start)*1000.0/Stopwatch.Frequency;rows.Add(new Row{frame=Time.frameCount,phase=(isCold?"cold-new-reader":"warm-facade")+"-"+scope,ms=ms,bytes=bytes<0?-1:allocated()-bytes});GC.KeepAlive(dto);if(++repeats>=target)running=false;}catch(Exception e){running=false;File.WriteAllText(Path.Combine(Root,"c1-error.json"),Json(new{frame=Time.frameCount,error=e.ToString()}));}}
 public static object Dispatch(JObject q)=>Instance.Command(q);
}
}
